-- ============================================================================
-- PRATYAKSH ACADEMIC FACIAL ATTENDANCE SYSTEM - MASTER POSTGRESQL SCHEMA
-- Includes pgvector extension, 10 core tables, and complete seed data.
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS vector;


CREATE TABLE IF NOT EXISTS students (
    student_id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(160),
    phone VARCHAR(40),
    date_of_birth DATE,
    program VARCHAR(160),
    semester VARCHAR(80),
    department VARCHAR(160),
    gpa VARCHAR(30),
    enrollment_year VARCHAR(10),
    section_id INTEGER,
    roll_number VARCHAR(50),
    profile_photo BYTEA,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS student_embeddings (
    id SERIAL PRIMARY KEY,
    student_id VARCHAR(50) REFERENCES students(student_id) ON DELETE CASCADE,
    embedding vector(512) NOT NULL,
    CONSTRAINT one_embedding_per_student UNIQUE (student_id)
);
CREATE INDEX IF NOT EXISTS embedding_hnsw_idx ON student_embeddings USING hnsw (embedding vector_cosine_ops);
CREATE UNIQUE INDEX IF NOT EXISTS student_embeddings_student_id_uidx ON student_embeddings(student_id);

CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(80) UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role VARCHAR(20) NOT NULL CHECK (role IN ('admin','teacher','student')),
    student_id VARCHAR(50) REFERENCES students(student_id) ON DELETE SET NULL,
    display_name VARCHAR(160),
    email VARCHAR(160),
    phone VARCHAR(40),
    profile_photo BYTEA,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS academic_sections (
    id SERIAL PRIMARY KEY,
    school VARCHAR(160) NOT NULL,
    faculty VARCHAR(160) NOT NULL,
    department VARCHAR(160) NOT NULL,
    program VARCHAR(160) NOT NULL,
    semester VARCHAR(80) NOT NULL,
    section VARCHAR(80) NOT NULL,
    UNIQUE(school, faculty, department, program, semester, section)
);

CREATE TABLE IF NOT EXISTS teacher_assignments (
    id SERIAL PRIMARY KEY,
    teacher_user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    section_id INTEGER REFERENCES academic_sections(id) ON DELETE CASCADE,
    subject VARCHAR(160) NOT NULL,
    UNIQUE(teacher_user_id, section_id, subject)
);

CREATE TABLE IF NOT EXISTS schedules (
    id SERIAL PRIMARY KEY,
    subject VARCHAR(120) NOT NULL,
    teacher VARCHAR(120) NOT NULL,
    room VARCHAR(80) NOT NULL,
    starts_at VARCHAR(10) NOT NULL,
    ends_at VARCHAR(10) NOT NULL,
    day VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS attendance_sessions (
    session_id VARCHAR(50) PRIMARY KEY,
    teacher_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    title VARCHAR(160) NOT NULL,
    course VARCHAR(160) NOT NULL,
    school VARCHAR(160) NOT NULL,
    faculty VARCHAR(160) NOT NULL,
    department VARCHAR(160) NOT NULL,
    program VARCHAR(160) NOT NULL,
    semester VARCHAR(80) NOT NULL,
    section_id INTEGER REFERENCES academic_sections(id) ON DELETE SET NULL,
    academic_scope JSONB,
    room VARCHAR(80),
    event_date DATE NOT NULL,
    starts_at TIME NOT NULL,
    ends_at TIME NOT NULL,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS attendance_logs (
    id SERIAL PRIMARY KEY,
    student_id VARCHAR(50) REFERENCES students(student_id) ON DELETE CASCADE,
    session_id VARCHAR(50) NOT NULL,
    confidence_score FLOAT NOT NULL,
    teacher_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    recognition_status VARCHAR(20) NOT NULL DEFAULT 'NOT_RECOGNIZED',
    initial_attendance_status VARCHAR(10) NOT NULL DEFAULT 'ABSENT',
    final_attendance_status VARCHAR(10),
    attendance_method VARCHAR(24) NOT NULL DEFAULT 'FACE_RECOGNITION',
    is_manual_override BOOLEAN NOT NULL DEFAULT FALSE,
    updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    timestamp TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT one_attendance_per_session UNIQUE (student_id, session_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS attendance_session_student_uidx ON attendance_logs(student_id, session_id);

-- Parent sessions may contain many independently scoped photograph batches.
ALTER TABLE attendance_sessions ADD COLUMN IF NOT EXISTS status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE attendance_sessions ADD COLUMN IF NOT EXISTS completed_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS attendance_upload_batches (
    id UUID PRIMARY KEY, session_id VARCHAR(50) NOT NULL REFERENCES attendance_sessions(session_id) ON DELETE CASCADE,
    submitted_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    section_id INTEGER REFERENCES academic_sections(id) ON DELETE SET NULL,
    program VARCHAR(160) NOT NULL, semester VARCHAR(80) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'PROCESSING', idempotency_key VARCHAR(100),
    total_files INTEGER NOT NULL DEFAULT 0, processed_files INTEGER NOT NULL DEFAULT 0,
    recognized_count INTEGER NOT NULL DEFAULT 0, duplicate_count INTEGER NOT NULL DEFAULT 0,
    unknown_faces INTEGER NOT NULL DEFAULT 0, failed_files INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMPTZ,
    UNIQUE (session_id, idempotency_key)
);
CREATE TABLE IF NOT EXISTS attendance_batch_photos (
    id UUID PRIMARY KEY, batch_id UUID NOT NULL REFERENCES attendance_upload_batches(id) ON DELETE CASCADE,
    filename VARCHAR(255) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PROCESSING',
    faces_detected INTEGER NOT NULL DEFAULT 0, recognized_count INTEGER NOT NULL DEFAULT 0,
    unknown_faces INTEGER NOT NULL DEFAULT 0, error_message TEXT, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS notifications (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    category VARCHAR(30) NOT NULL,
    title VARCHAR(160) NOT NULL,
    body TEXT NOT NULL,
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS audit_logs (
    id SERIAL PRIMARY KEY,
    actor_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    action VARCHAR(80) NOT NULL,
    entity VARCHAR(80) NOT NULL,
    entity_id VARCHAR(120),
    previous_value JSONB,
    new_value JSONB,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);


